keyConcepts.code:
SELECT id_pedido, valor,
  SUM(valor) OVER (PARTITION BY id_vendedor) AS total_vendedor
FROM pedidos;

keyConcepts.altCode:
SELECT id_vendedor, SUM(valor) AS total_vendedor
FROM pedidos
GROUP BY id_vendedor;

questions.sample:
SELECT id_pedido, valor,
    SUM(valor) OVER (PARTITION BY id_vendedor) AS total_vendedor
FROM pedidos;

SELECT id_pedido, data_pedido, valor,
    SUM(valor) OVER (PARTITION BY id_vendedor ORDER BY data_pedido) AS receita_acumulada
FROM pedidos;
